// TestMultiContourStrokeFillGolden verifies our rasterizer produces
// deterministic, pixel-exact output for a multi-contour stroke-expanded
// path (outer CW + inner CCW, NonZero fill rule).
//
// The golden image was generated by our own rasterizer. Any change in
// coverage output will be caught as a regression.
func TestMultiContourStrokeFillGolden(t *testing.T) {
	got := renderMultiContourFolder(20, 20)
	golden := loadGoldenPNG(t, "multicontour-fill-20x20.png")
	result := compareImages(got, golden)
	logCompareResult(t, "multi-contour stroke fill (regression)", result)

	if result.DiffCount > 0 {
		t.Errorf("regression: %d pixels differ (max_diff=%d), want exact match",
			result.DiffCount, result.MaxDiff)
	}
}

// TestMultiContourVsSkiaAAA compares our output against Skia AAA golden
// (generated via fiddle.skia.org, hash 787e4807f1d8e445a262180d3a9c5578)
// with per-pixel exact diff verification.
//
// Every differing pixel is accounted for in expectedSkiaDiffR. The test
// fails if ANY pixel has an unexpected diff or a known diff changes value.
// This catches both regressions and unintended improvements.
//
// Root cause of diffs: different quad curve evaluation methods.
//   - Ours: recursive De Casteljau subdivision (0.1px tolerance, float).
//     Chosen for stability — FDot6 forward-diff produced zero-height
//     segments that lost winding contribution (issue #148, v0.32.3).
//   - Skia: FDot6 forward-differencing (O(1)/step, 1/8px accuracy).
//     Chosen for performance — O(1) per edge step, cache-friendly.
//
// Ground truth (200×200 supersample) shows our coverage is closer to
// mathematical truth: max|ours−GT|=21 vs max|skia−GT|=31.
// All 21 diffs are on QuadTo curve corners. Straight edges: diff==0.
func TestMultiContourVsSkiaAAA(t *testing.T) {
	// Exact per-pixel expected diff (our R − Skia R).
	// Positive = our coverage higher, negative = lower.
	// All entries are on QuadTo curve corners where geometric flattening
	// (ours) and FDot6 forward-differencing (Skia) produce different
	// sub-pixel edge positions.
	expectedSkiaDiffR := map[[2]int]int{
		// Top-left corner (outer QuadTo 1.25,2.75→3.25,2.75 + inner 2.25,3.75→...)
		{2, 2}: +3, {1, 3}: +8, {2, 3}: -5, {1, 4}: +7, {2, 4}: +5,
		// Tab notch diagonal (LineTo 10.84,5.19→11.05,5.37 + QuadTo curves)
		{9, 4}: -1,
		// Top-right corner (outer QuadTo 18.75,5.25→18.75,7)
		{17, 5}: +25, {18, 5}: +6, {17, 6}: -8, {18, 6}: +12,
		// Bottom-left corner (outer QuadTo 1.25,17.25→1.25,15.17)
		{1, 15}: +7, {2, 15}: -5, {1, 16}: +8, {2, 16}: -6,
		// Bottom-right corner (outer QuadTo 18.75,17.25→16.75,17.25)
		{17, 15}: -5, {18, 15}: +7, {17, 16}: -6, {18, 16}: +8,
		// Bottom edge (outer QuadTo endpoints)
		{2, 17}: +3, {3, 17}: -1, {17, 17}: +3,
	}

	got := renderMultiContourFolder(20, 20)
	skia := loadGoldenPNG(t, "stroke-expanded-fill-20x20.png")
	w, h := 20, 20
	failed := false

	for y := range h {
		for x := range w {
			ourR := int(got.RGBAAt(x, y).R)
			skiaR := int(skia.RGBAAt(x, y).R)
			actualDiff := ourR - skiaR

			expected, known := expectedSkiaDiffR[[2]int{x, y}]
			if known {
				if actualDiff != expected {
					t.Errorf("(%d,%d): diff changed: got %+d, expected %+d", x, y, actualDiff, expected)
					failed = true
				}
			} else if actualDiff != 0 {
				t.Errorf("(%d,%d): unexpected diff %+d (not in known diff table)", x, y, actualDiff)
				failed = true
			}
		}
	}

	if !failed {
		t.Logf("PASS: all %d known Skia AAA diffs match exactly (max R diff: 25)", len(expectedSkiaDiffR))
	}
}

func TestMultiContourCoverageDump(t *testing.T) {
	path := buildExpandedFolderPath()

	w, h := 20, 20
	eb := NewEdgeBuilder(2)
	eb.SetFlattenCurves(true)
	eb.BuildFromPath(path, IdentityTransform{})

	coverageBuf := make([]uint8, w*h)
	FillToBuffer(eb, w, h, FillRuleNonZero, coverageBuf)

	t.Log("Coverage map (hex):")
	for y := range h {
		row := ""
		for x := range w {
			c := coverageBuf[y*w+x]
			if c == 0 {
				row += "  ."
			} else {
				row += fmt.Sprintf(" %02X", c)
			}
		}
		t.Logf("  y%02d:%s", y, row)
	}
}

